    final StringBuilder sb = new StringBuilder( len );

    int i = 0;
    while ( i < len )
    {
        c = s.charAt( i++ );
        if ( c == '\\' )
        {
            c = s.charAt( i++ );
            if ( c == 'n' )
            {
                c = '\n';
